**Pseudocódigo para o DistributedLock com Supabase/Postgres:**
javascript
// Exemplo de pseudo-código para gestão de lock de sessão no PostgreSQL/Supabase
class DistributedSessionLock {
  constructor(supabaseClient) {
    this.supabase = supabaseClient;
  }

  async acquireLock(sessionId, instanceId, timeoutMs = 30000) {
    const expiresAt = new Date(Date.now() + timeoutMs);
    try {
      const { data, error } = await this.supabase
        .from('session_locks')
        .upsert(
          { session_id: sessionId, instance_id: instanceId, expires_at: expiresAt.toISOString() },
          { onConflict: 'session_id', ignoreDuplicates: false }
        )
        .select('instance_id');

      if (error && error.code === '23505') { // Unique violation means another instance holds the lock
        // Check if the existing lock is expired
        const { data: existingLock, error: fetchError } = await this.supabase
          .from('session_locks')
          .select('*')
          .eq('session_id', sessionId)
          .single();

        if (fetchError || !existingLock || new Date(existingLock.expires_at) < new Date()) {
          // Lock is expired or doesn't exist, try to force acquire
          const { data: updatedLock, error: updateError } = await this.supabase
            .from('session_locks')
            .update({ instance_id: instanceId, expires_at: expiresAt.toISOString() })
            .eq('session_id', sessionId)
            .select('instance_id');

          if (!updateError && updatedLock && updatedLock[0].instance_id === instanceId) {
            return true; // Successfully acquired by updating expired lock
          }
        }
        return false; // Lock held by another instance or failed to acquire/update
      }
      if (error) throw error;
      return data && data[0].instance_id === instanceId; // Acquired successfully

    } catch (e) {
      console.error(`Error acquiring lock for ${sessionId}:`, e.message);
      return false;
    }
  }

  async releaseLock(sessionId, instanceId) {
    const { error } = await this.supabase
      .from('session_locks')
      .delete()
      .eq('session_id', sessionId)
      .eq('instance_id', instanceId); // Only delete if this instance holds the lock

    if (error) {
      console.error(`Error releasing lock for ${sessionId}:`, error.message);
      return false;
    }
    return true;
  }
}

