    javascript
    import { supabase } from '../config/supabaseClient'; // Assumindo configuração do cliente Supabase

    async function pauseAIChat(chatId, durationInMinutes) {
        const pauseUntil = new Date(Date.now() + durationInMinutes * 60 * 1000);
        const { data, error } = await supabase
            .from('chats') // Ou 'conversations'
            .update({ ai_paused_until: pauseUntil.toISOString() })
            .eq('id', chatId);

        if (error) {
            console.error('Erro ao pausar IA no Supabase:', error.message);
            throw new Error('Falha ao pausar IA.');
        }
        return data;
    }

    async function isAIPaused(chatId) {
        const { data, error } = await supabase
            .from('chats')
            .select('ai_paused_until')
            .eq('id', chatId)
            .single();

        if (error && error.code !== 'PGRST116') { // PGRST116 é 'no rows found'
            console.error('Erro ao verificar status da IA:', error.message);
            return false; // Assumir que não está pausada em caso de erro
        }

        if (!data || !data.ai_paused_until) {
            return false; // Não há registro ou não está pausada
        }

        const pauseUntilDate = new Date(data.ai_paused_until);
        return pauseUntilDate > new Date(); // Retorna true se a data de pausa ainda não passou
    }


