    javascript
    // Exemplo de pseudo-código
    async function fetchContactPicture(contactId, maxRetries = 3, delay = 1000) {
        for (let i = 0; i < maxRetries; i++) {
            try {
                const response = await fetch(`https://api.example.com/profilepictures/${contactId}`); // URL de exemplo
                if (!response.ok) {
                    throw new Error(`HTTP error! status: ${response.status}`);
                }
                const blob = await response.blob();
                return URL.createObjectURL(blob);
            } catch (error) {
                console.error(`Tentativa ${i + 1} falhou para ${contactId}:`, error);
                if (error instanceof TypeError && error.message === 'Failed to fetch' && i < maxRetries - 1) {
                    await new Promise(res => setTimeout(res, delay * Math.pow(2, i)));
                } else {
                    throw error; // Re-lança o erro final se todas as tentativas falharem ou for um erro diferente
                }
            }
        }
    }

